// Synthetic, unshown WPF verification. No screenshots/assets/files, HWND creation,
// real endpoints, device processes, external links or native device APIs are used.
using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Interop;
using System.Windows.Media;
using RogControl;

internal static class HeadsetAudioGuiTests {
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static int Count;
 static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);Count++;}
 static object Get(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static object Invoke(MainWindow window,string name,params object[] args){return typeof(MainWindow).GetMethod(name,Hidden).Invoke(window,args);}
 static IEnumerable<DependencyObject> Walk(DependencyObject node){yield return node;foreach(object item in LogicalTreeHelper.GetChildren(node)){var child=item as DependencyObject;if(child!=null)foreach(var next in Walk(child))yield return next;}}
 static List<FrameworkElement> Nodes(MainWindow window){return Walk((DependencyObject)Get(window,"content")).OfType<FrameworkElement>().ToList();}
 static T Tagged<T>(MainWindow window,string tag) where T:FrameworkElement{return Nodes(window).OfType<T>().Single(element=>Convert.ToString(element.Tag)==tag);}
 static void NoNative(MainWindow window){Check(new WindowInteropHelper(window).Handle==IntPtr.Zero,"no HWND created");foreach(var field in typeof(MainWindow).GetFields(Hidden).Where(field=>field.FieldType==typeof(WorkerClient))){var client=(WorkerClient)field.GetValue(window);Check(typeof(WorkerClient).GetField("process",Hidden).GetValue(client)==null,"no worker created: "+field.Name);}}
 static Dictionary<string,object> State(){return new Dictionary<string,object>{{"online",true},{"deviceId","synthetic-headset"},{"setCapabilities",new object[]{"eqEnabled","eqLevels","noiseReductionEnabled","noiseReductionRaw","voicePrompt","sideToneEnabled","sideToneLevel","latencyMs"}},{"snapshot",new Dictionary<string,object>{{"eqEnabled",true},{"eqLevels",new object[]{0,25,40,50,60,75,90,100}},{"noiseReductionEnabled",false},{"noiseReductionRaw",1},{"voicePrompt",2},{"sideToneEnabled",true},{"sideToneLevel",7},{"latencyMs",60}}}};}
 static Dictionary<string,object> Endpoint(string flow,string id,object volume){return new Dictionary<string,object>{{"endpointId",id},{"flow",flow},{"name","Synthetic DELTA II-KJP "+flow},{"matchConfirmed",true},{"active",true},{"readbackConfirmed",true},{"volumePercent",volume},{"muted",false}};}
 static void Page(MainWindow window,string method,Dictionary<string,object> state){var panel=(StackPanel)Get(window,"content");panel.Children.Clear();Invoke(window,method,panel,state);}
 static void Layout(MainWindow window,int width){var frame=(FrameworkElement)window.Content;int height=width==1538?826:726;((ScrollViewer)Get(window,"pageScroll")).ScrollToTop();frame.Measure(new Size(width,height));frame.Arrange(new Rect(0,0,width,height));frame.UpdateLayout();}

 [STAThread]public static int Main(){try{
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new MainWindow(true);NoNative(window);
  var header=(StackPanel)Get(window,"fixedPageHeader");header.Children.Clear();header.Height=99;
  foreach(int width in new[]{1538,1180}) {
   foreach(string tab in new[]{"均衡器","优化","音效增强"}){Set(window,"headsetAudioTab",tab);Page(window,"OriginalHeadsetAudioPage",null);Layout(window,width);var nodes=Nodes(window);Check(nodes.OfType<ComboBox>().All(control=>!control.IsEnabled),"unknown audio combo disabled");Check(nodes.OfType<CheckBox>().All(control=>!control.IsEnabled&&control.IsChecked==null),"unknown audio switches have no state");Check(nodes.OfType<Slider>().All(control=>!control.IsEnabled),"unknown audio sliders disabled");Check(nodes.OfType<Canvas>().Count(control=>Convert.ToString(control.Tag)=="headset:ownArtwork")==1,"audio owns generic line artwork");NoNative(window);}
   foreach(bool expanded in new[]{false,true}){Set(window,"headsetNoiseExpanded",expanded);Page(window,"OriginalHeadsetMicrophonePage",null);Layout(window,width);Check(!Nodes(window).OfType<Canvas>().Any(control=>Convert.ToString(control.Tag)=="headset:ownArtwork"),"microphone has no left product");Check(Nodes(window).OfType<ComboBox>().All(control=>!control.IsEnabled),"unknown noise strength disabled");Check(Nodes(window).OfType<CheckBox>().All(control=>!control.IsEnabled&&control.IsChecked==null),"unknown microphone state");NoNative(window);}
   foreach(string tab in new[]{"音量","高级功能","快捷键说明"}){Set(window,"headsetSettingsTab",tab);Page(window,"OriginalHeadsetSettingsPage",null);Layout(window,width);Check(Nodes(window).OfType<ComboBox>().All(control=>!control.IsEnabled),"unknown settings combos disabled");Check(Nodes(window).OfType<Slider>().All(control=>!control.IsEnabled),"unknown settings sliders disabled");NoNative(window);}
   Set(window,"headsetSettingsTab","高级功能");Page(window,"OriginalHeadsetSettingsPage",State());Layout(window,width);var viewer=Nodes(window).OfType<ScrollViewer>().Single();Check(width==1538?viewer.ScrollableWidth<=18:viewer.ScrollableWidth>300,"fixed surface horizontal overflow is reachable");viewer.ScrollToRightEnd();((ScrollViewer)Get(window,"pageScroll")).ScrollToBottom();((FrameworkElement)window.Content).UpdateLayout();var language=Tagged<ComboBox>(window,"headset:voicePrompt");Rect bounds=language.TransformToAncestor((FrameworkElement)window.Content).TransformBounds(new Rect(0,0,language.ActualWidth,language.ActualHeight));Check(bounds.Right<=width-21&&bounds.Left>=248,"rightmost settings controls reachable");NoNative(window);
  }
  Set(window,"headsetAudioTab","均衡器");Page(window,"OriginalHeadsetAudioPage",State());var gains=Nodes(window).OfType<Slider>().Where(control=>Convert.ToString(control.Tag).StartsWith("headset:eqGain:")).ToArray();Check(gains.Length==8,"eight EQ bands");Check(gains.Select(control=>(int)control.Value).SequenceEqual(new[]{0,25,40,50,60,75,90,100}),"readback raw gains preserved");Check(gains.All(control=>control.IsEnabled),"known exact capabilities permit local draft");gains[0].Value=35;Tagged<CheckBox>(window,"headset:eqEnabled").IsChecked=false;Check(!Tagged<Button>(window,"headset:apply:eqLevels").IsEnabled,"render policy blocks EQ apply");Tagged<Button>(window,"headset:apply:eqLevels").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Tagged<Button>(window,"headset:apply:eqEnabled").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));NoNative(window);
  var shortGains=State();((Dictionary<string,object>)shortGains["snapshot"])["eqLevels"]=new object[]{50};Page(window,"OriginalHeadsetAudioPage",shortGains);Check(!Tagged<Button>(window,"headset:apply:eqLevels").IsEnabled,"partial EQ readback cannot apply");Check(Nodes(window).OfType<Slider>().Count(control=>control.IsEnabled)==1,"missing gains remain unknown");NoNative(window);
  var invalidGains=State();((Dictionary<string,object>)invalidGains["snapshot"])["eqLevels"]=new object[]{true,Double.NaN,101,-1,1.5,"invalid",null,50};Page(window,"OriginalHeadsetAudioPage",invalidGains);Check(Nodes(window).OfType<Slider>().Count(control=>control.IsEnabled)==1,"invalid EQ values rejected");NoNative(window);
  var offline=State();offline["online"]=false;Page(window,"OriginalHeadsetAudioPage",offline);Check(Nodes(window).OfType<Slider>().All(control=>!control.IsEnabled),"offline EQ is not current");Check(Tagged<CheckBox>(window,"headset:eqEnabled").IsChecked==null,"offline enabled state not reused");NoNative(window);
  Set(window,"headsetNoiseExpanded",true);Page(window,"OriginalHeadsetMicrophonePage",State());var noise=Tagged<ComboBox>(window,"headset:noiseReductionRaw");Check(noise.SelectedIndex==2&&noise.IsEnabled,"noise raw1 maps to medium");noise.SelectedIndex=3;Tagged<Button>(window,"headset:apply:noiseReductionRaw").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));NoNative(window);
  Set(window,"headsetSettingsTab","高级功能");Page(window,"OriginalHeadsetSettingsPage",State());Check(Tagged<ComboBox>(window,"headset:voicePrompt").SelectedIndex==3,"voice prompt2 maps to Chinese");Check(Tagged<ComboBox>(window,"headset:latencyMs").SelectedIndex==2,"latency60 preserved");Check(Tagged<Slider>(window,"headset:sideToneLevel").Value==7,"side tone raw7 preserved");Tagged<ComboBox>(window,"headset:voicePrompt").SelectedIndex=1;Tagged<Slider>(window,"headset:sideToneLevel").Value=12;Tagged<CheckBox>(window,"headset:sideToneEnabled").IsChecked=false;foreach(var apply in Nodes(window).OfType<Button>().Where(control=>Convert.ToString(control.Tag).StartsWith("headset:apply:"))){Check(!apply.IsEnabled,"render apply disabled");apply.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}NoNative(window);
  var noCaps=State();noCaps["setCapabilities"]=new object[0];Page(window,"OriginalHeadsetSettingsPage",noCaps);Check(Nodes(window).OfType<ComboBox>().All(control=>!control.IsEnabled),"missing setting capability disabled");Check(Nodes(window).OfType<Slider>().All(control=>!control.IsEnabled),"missing slider capability disabled");NoNative(window);
  var endpoints=(List<Dictionary<string,object>>)Get(window,"audioEndpoints");endpoints.Add(Endpoint("render","synthetic-playback",48.6));endpoints.Add(Endpoint("capture","synthetic-capture",20));Set(window,"headsetSettingsTab","音量");Page(window,"OriginalHeadsetSettingsPage",null);Check(Tagged<Slider>(window,"headset:windowsVolume:render").Value==49&&Tagged<Slider>(window,"headset:windowsVolume:render").IsEnabled,"matched playback current volume draft");Check(Tagged<Slider>(window,"headset:windowsVolume:capture").Value==20,"capture flow separate");Tagged<Slider>(window,"headset:windowsVolume:render").Value=60;Tagged<CheckBox>(window,"headset:windowsMute:render").IsChecked=true;Tagged<Button>(window,"headset:applyWindowsVolume:render").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Tagged<Button>(window,"headset:applyWindowsMute:render").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Tagged<Button>(window,"headset:readWindows:render").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));NoNative(window);
  endpoints[0]["volumePercent"]=Double.NaN;Page(window,"OriginalHeadsetSettingsPage",null);Check(!Tagged<Slider>(window,"headset:windowsVolume:render").IsEnabled,"invalid Windows current volume unknown");NoNative(window);
  endpoints[0]["volumePercent"]=48;endpoints[0]["matchConfirmed"]=false;Page(window,"OriginalHeadsetSettingsPage",null);Check(!Tagged<Slider>(window,"headset:windowsVolume:render").IsEnabled,"foreign endpoint cannot enable slider");NoNative(window);
  endpoints[0]["matchConfirmed"]=true;endpoints.Add(Endpoint("render","synthetic-second",30));Page(window,"OriginalHeadsetSettingsPage",null);Check(Nodes(window).OfType<ComboBox>().Single().Items.Count==3,"multiple endpoints require identity selection");Check(Nodes(window).OfType<Canvas>().Any(control=>control.Width==1176&&control.Height==120),"multiple endpoint selector has space");NoNative(window);
  var policy=(HardwareControlPolicy)Get(window,"hardwareControlPolicy");Check(!policy.Enabled,"session consent defaults off");policy.SetEnabled(true);Set(window,"headsetSettingsTab","高级功能");Page(window,"OriginalHeadsetSettingsPage",State());Check(Nodes(window).OfType<Button>().Where(control=>Convert.ToString(control.Tag).StartsWith("headset:apply:")).All(control=>!control.IsEnabled),"render-only cannot gain write access from session consent");NoNative(window);policy.SetEnabled(false);
  var gearStates=(Dictionary<string,Dictionary<string,object>>)Get(window,"gearStates");gearStates.Remove("headset");endpoints.Clear();((Dictionary<string,string>)Get(window,"audioEndpointSelection")).Clear();Set(window,"gearMessage","");header.Height=Double.NaN;var gearTabs=(Dictionary<string,string>)Get(window,"gearTabs");
  foreach(int width in new[]{1538,1180})foreach(string branch in new[]{"audio:eq","audio:optimization","audio:enhancement","microphone","settings:volume","settings:advanced","settings:shortcuts"}) {
   gearTabs["headset"]=branch.StartsWith("audio:")?"音效":branch.StartsWith("settings:")?"设置":"麦克风";Set(window,"headsetAudioTab",branch=="audio:optimization"?"优化":branch=="audio:enhancement"?"音效增强":"均衡器");Set(window,"headsetSettingsTab",branch=="settings:advanced"?"高级功能":branch=="settings:shortcuts"?"快捷键说明":"音量");Set(window,"headsetNoiseExpanded",false);
   Invoke(window,"ShowPage","device:headset");Layout(window,width);var viewer=Nodes(window).OfType<ScrollViewer>().Single();double origin=viewer.TransformToAncestor((FrameworkElement)window.Content).Transform(new Point(0,0)).Y;Check(Math.Abs(origin-117)<0.1,"integrated body origin117: "+branch);Check(Nodes(window).OfType<Canvas>().Any(control=>Convert.ToString(control.Tag)=="headset:surface"),"integrated headset branch: "+branch);NoNative(window);
  }
  // Only locally authored settings-tab/expander callbacks are fired. Never invoke
  // the device header's web, firmware, download or any external-link buttons.
  gearTabs["headset"]="设置";Set(window,"headsetSettingsTab","音量");Invoke(window,"ShowPage","device:headset");Nodes(window).OfType<Button>().Single(control=>control.Content is TextBlock&&((TextBlock)control.Content).Text=="高级功能").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((string)Get(window,"headsetSettingsTab")=="高级功能","settings tab local navigation");NoNative(window);
  gearTabs["headset"]="麦克风";Invoke(window,"ShowPage","device:headset");Tagged<Button>(window,"headset:noiseExpand").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((bool)Get(window,"headsetNoiseExpanded"),"noise expansion local only");NoNative(window);
  Console.WriteLine("PASS "+Count+" headset GUI checks; HWNDs=0; workers=0; real hardware GET/write=0; external links=0");return 0;
 }catch(Exception error){Console.Error.WriteLine("FAIL after "+Count+" checks");for(Exception current=error;current!=null;current=current.InnerException)Console.Error.WriteLine(current.GetType().FullName+": "+current.Message);return 1;}}
}
